// "Built" output: what the published package ships. The `override`
// keyword is type-only, so the author's emit and a scriptc-forced emit of
// the same source are the same JavaScript — which is what lets the
// source-static binary be held against this file byte for byte.
class Rule {
  label() {
    return "rule";
  }
  weight() {
    return 1;
  }
}
class StrictRule extends Rule {
  label() {
    return "strict";
  }
  weight() {
    return 2;
  }
}
export function ruleReport() {
  const base = new Rule();
  const strict = new StrictRule();
  return `${base.label()}:${base.weight()} ${strict.label()}:${strict.weight()}`;
}
export function amplify(n) {
  return n * new StrictRule().weight();
}
